package com.campusnova.controller;
import com.campusnova.model.OfficialKnowledge; import com.campusnova.repository.OfficialKnowledgeRepository; import com.campusnova.service.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/official-knowledge") public class AdminKnowledgeController { private final AuthService auth; private final OfficialKnowledgeImportService importer; private final OfficialKnowledgeRepository knowledge; public AdminKnowledgeController(AuthService a,OfficialKnowledgeImportService i,OfficialKnowledgeRepository k){auth=a;importer=i;knowledge=k;} private void guard(String token){if(!auth.valid(token))throw new SecurityException("Administrator login required");} @GetMapping public List<OfficialKnowledge> list(@RequestHeader("X-Admin-Token")String token){guard(token);return knowledge.findAll();} @PostMapping("/import-core") public List<OfficialKnowledge> importCore(@RequestHeader("X-Admin-Token")String token){guard(token);return importer.importCorePages();} @PostMapping("/import") public OfficialKnowledge importOne(@RequestHeader("X-Admin-Token")String token,@RequestParam String url)throws java.io.IOException{guard(token);return importer.importUrl(url);} }
